WITH metrics AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, CORR(status_bits, humidity) OVER (PARTITION BY device_code) AS corr_status_bits_humidity, SUM(pressure) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_pressure, SUM(humidity) OVER (PARTITION BY device_code ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_humidity FROM device_readings) SELECT id, device_code, temp_c, humidity, status_bits, firmware, corr_status_bits_humidity, running_pressure FROM metrics ORDER BY corr_status_bits_humidity DESC, humidity DESC;
